  "knowledgeIndex": {
    "id": "knowledgeIndex",
    "title": "Knowledge index",
    "description": "One project's knowledge index: queued, indexing, ready, stale when the files changed since it was built, or failed. The build in the store (src/core/knowledge/store.ts) drives the events — started by a request that needs it, and by the Files panel's add/remove, in the background; the Project knowledge screen shows the state it observes.",
    "initial": "queued",
    "states": [
      {
        "id": "queued",
        "label": "Queued",
        "description": "The index does not exist yet; the first request that needs it — or the Files panel's add — builds it."
      },
      {
        "id": "indexing",
        "label": "Indexing",
        "description": "The sections are being cut and the store is being written; the panel sees n of m."
      },
      {
        "id": "ready",
        "label": "Ready",
        "description": "The index matches the files and retrieval reads from it."
      },
      {
        "id": "stale",
        "label": "Stale",
        "description": "The project's files changed after the index was built; the next request — or the Files panel's change — rebuilds it."
      },
      {
        "id": "failed",
        "label": "Failed",
        "description": "The build could not finish; the next request tries again, and the panel's Retry does the same."
      }
    ],
    "transitions": [
      {
        "from": "queued",
        "to": "indexing",
        "event": "indexing",
        "description": "A first build begins."
      },
      {
        "from": "ready",
        "to": "stale",
        "event": "files_changed",
        "description": "The project's files changed after the index was built."
      },
      {
        "from": "stale",
        "to": "indexing",
        "event": "reindex",
        "description": "The next request rebuilds the index over the changed files."
      },
      {
        "from": "failed",
        "to": "indexing",
        "event": "retry",
        "description": "The next request tries the build again."
      },
      {
        "from": "indexing",
        "to": "indexing",
        "event": "restart",
        "description": "A build that died mid-way (its tracker still says indexing) starts over."
      },
      {
        "from": "indexing",
        "to": "ready",
        "event": "indexed",
        "description": "The sections were cut and the store was written (or works from memory)."
      },
      {
        "from": "indexing",
        "to": "failed",
        "event": "failed",
        "description": "The build could not finish; the error is named, not swallowed."
      }
    ],
    "rejects": [
      [
        "queued",
        "ready"
      ],
      [
        "queued",
        "stale"
      ],
      [
        "ready",
        "indexing"
      ],
      [
        "failed",
        "ready"
      ],
      [
        "failed",
        "stale"
      ],
      [
        "stale",
        "ready"
      ]
    ]
  },
  "agentRun": {
    "id": "agentRun",
    "title": "Agent run",
    "description": "One Computer Use run against ONE target: either a single granted window (the sidecar loop observes, proposes, acts and verifies inside it) or a saved Word document edited as a copy (the Edit-a-copy loop reads it, proposes text edits, applies them to the copy and reopens the copy to verify). Either loop runs until the task is done, the person stops it, or a limit or failure settles it.",
    "initial": "running",
    "states": [
      {
        "id": "running",
        "label": "Running",
        "description": "The loop is observing, proposing, acting or verifying — inside the granted window, or on the document copy."
      },
      {
        "id": "done",
        "label": "Done",
        "description": "The model reported the task complete and every action it took was verified against the window, or the edited copy was verified against the source."
      },
      {
        "id": "unresolved",
        "label": "Unresolved",
        "description": "The loop stopped without proving success: an action could not be verified, a step limit was reached, the model gave up after changes were already made, or the edited copy failed its verification."
      },
      {
        "id": "failed",
        "label": "Failed",
        "description": "The run could not continue: the window disappeared, the driver died, or no usable proposal was produced."
      },
      {
        "id": "cancelled",
        "label": "Cancelled",
        "description": "The person pressed stop; a person's stop settles cancelled, never failed."
      }
    ],
    "transitions": [
      {
        "from": "running",
        "to": "done",
        "event": "done",
        "description": "The model said the task is complete and all actions verified."
      },
      {
        "from": "running",
        "to": "unresolved",
        "event": "unresolved",
        "description": "Unverified actions, the step limit, or a give-up after changes settled the run."
      },
      {
        "from": "running",
        "to": "failed",
        "event": "failed",
        "description": "The window, the driver or the model answer was lost."
      },
      {
        "from": "running",
        "to": "cancelled",
        "event": "cancelled",
        "description": "The person stopped the run."
      }
    ],
    "rejects": [
      [
        "done",
        "running"
      ],
      [
        "cancelled",
        "running"
      ],
      [
        "failed",
        "running"
      ],
      [
        "unresolved",
        "running"
      ],
      [
        "done",
        "failed"
      ],
      [
        "cancelled",
        "failed"
      ]
    ]
  },
